      "summary": "首页 > 科研进展 碱性水电解制氢被认为是最具产业化潜力的绿氢制备路线之一，而在大电流密度条件下，剧烈气泡析出、局部传质受阻及催化层脱落等问题，制约了电极效率与长期稳定性。因此，构建兼具高活性、高传质效率和高结构稳定性的析氢电极，是推动高效绿氢装备发展的关键。 近日，中国科学院上海高等研究院在碱性大电流密度析氢电极研究",
