      "matchedTopic": "科学前沿与科研设施",
      "rawText": "首页 > 科研进展 碱性水电解制氢被认为是最具产业化潜力的绿氢制备路线之一，而在大电流密度条件下，剧烈气泡析出、局部传质受阻及催化层脱落等问题，制约了电极效率与长期稳定性。因此，构建兼具高活性、高传质效率和高结构稳定性的析氢电极，是推动高效绿氢装备发展的关键。 近日，中国科学院上海高等研究院在碱性大电流密度析氢电极研究方面取得进展。团队围绕纳米孔氢气限域—气泡管理—多相传质之间的耦合关系，开发出一种整体式纯镍相电极。该电极通过结构化成型与原位热转化相结合，在保持整体机械强度的同时原位生成活性镍纳米结构，避免了传统喷涂型析氢电极中常见的界面电阻、活性层堵塞和催化剂脱落等问题，为安培级碱性水电解制",
