      "matchedTopic": "科学前沿动态",
      "rawText": "作者：姚雪青 来源：人民日报 发布时间：2026/6/5 15:00:14 中国科学院院士朱茂炎：给地球生命书写“远古家谱” 人物小传 朱茂炎，1963年12月生，安徽望江人，中国科学院院士，中国科学院南京地质古生物研究所研究员。他长期致力于新元古代至寒武纪地球环境和生命演化的研究。其团队原创研究成果曾入选《科学》杂志“2024年度十大科学突破”、“中国基础研究十大新闻”以及“中国十大科技进展新闻”，5次入选“中国古生物学十大进展”，两次入选“十大地质科技进展”。曾获中国科学院自然科学奖特等奖，江苏省科学技术奖一等奖等。 朱茂炎（右一）带领团队开展野外工作。王宁生摄",
